return CorrelationContext.current().flatMap(requestId -> {
    LOGGER.info("packet received deviceId={} requestId={}", packet.deviceId(), requestId);
    meters.packetReceived(packet.sourceKind());
    Instant start = clock.instant();
    return Flux.fromIterable(packet.samples())
        .concatMap(sample -> {
            boolean accepted = properties.boundaries().stream()
                .noneMatch(boundary -> boundary.enabled() && boundary.metric() == sample.metric()
                    && !boundary.accepts(sample.value()));
            ValidationStatus status = accepted ? ValidationStatus.VALID : ValidationStatus.VALIDATION_FAILED;
            meters.sampleValidated(sample.metric(), status);
            if (accepted) {
                LOGGER.info("sample validated metric={} requestId={}", sample.metric(), requestId);
            } else {
                LOGGER.info("sample tagged VALIDATION_FAILED requestId={} metric={}", requestId, sample.metric());
            }
            return stream.publish(new ValidatedSampleEvent(sample.withStatus(status), requestId))
                .then(Mono.defer(() -> auditTrail.record(new AuditEntry(packet.deviceId(),
                    AuditAction.VALIDATE_SAMPLE, "SUCCESS", clock.instant(), requestId))));
        })
        .then(Mono.defer(() -> auditTrail.record(new AuditEntry(packet.deviceId(),
            AuditAction.INGEST_PACKET, "SUCCESS", clock.instant(), requestId))))
        .onErrorResume(error -> auditTrail.record(new AuditEntry(packet.deviceId(),
                AuditAction.INGEST_PACKET, "FAILURE", clock.instant(), requestId))
            .then(Mono.<Void>error(error)))
        .doFinally(signal -> meters.recordLatency("validate", Duration.between(start, clock.instant())));
});
